from collections import deque
def bfs(graph, start, goal):
    q = deque([(start, 0)])
    seen = {start}
    while q:
        v, d = q.popleft()
        if v == goal: return d
        for nb in graph.get(v, ()):
            if nb not in seen:
                seen.add(nb)
                q.append((nb, d + 1))
    return -1
```

